settings.custom_liquid:
{%- liquid
  assign bc_col = nil
  if product
    assign bc_col = product.metafields.custom.collectie.value
  endif

  assign bc_label = page_title | default: 'Pagina'
  assign bc_show_mid = false
  assign bc_mid_label = nil
  assign bc_mid_url = nil

  if template.name == 'product' and product
    assign bc_label = product.title

    if bc_col != blank
      assign bc_show_mid = true
      assign bc_mid_label = bc_col.title
      assign bc_mid_url = bc_col.url
    elsif collection
      assign bc_show_mid = true
      assign bc_mid_label = collection.title
      assign bc_mid_url = collection.url
    elsif product.collections.size > 0
      assign bc_show_mid = true
      assign bc_mid_label = product.collections.first.title
      assign bc_mid_url = product.collections.first.url
    endif

  elsif template.name == 'collection' and collection
    assign bc_label = collection.title

  elsif template.name == 'page' and page
    assign bc_label = page.title

  elsif template.name == 'blog' and blog
    assign bc_label = blog.title

  elsif template.name == 'article' and article and blog
    assign bc_show_mid = true
    assign bc_mid_label = blog.title
    assign bc_mid_url = blog.url
    assign bc_label = article.title

  elsif template.name == 'search'
    assign bc_label = 'Search'

  elsif template.name == 'cart'
    assign bc_label = 'Cart'
  endif
-%}

<div class="rt-bc-outer page-width">
  <nav class="rt-bc" aria-label="Breadcrumb">
    <ol class="rt-bc__list" role="list">

      <!-- Home icon -->
      <li class="rt-bc__item">
        <a class="rt-bc__link rt-bc__home" href="{{ routes.root_url }}" aria-label="Home">
          <span class="rt-bc__home-ico" aria-hidden="true">
            <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
              <path d="M3.012,10.981,3,11H5v9a1,1,0,0,0,1,1H18a1,1,0,0,0,1-1V11h2a1,1,0,0,1,.555-1.832l-9-6a1,1,0,0,0-1.11,0l-9,6a1,1,0,0,0-.277,1.387A.98.98,0,0,0,3.012,10.981ZM10,14a1,1,0,0,1,1-1h2a1,1,0,0,1,1,1v5H10Z"></path>
            </svg>
          </span>
        </a>
      </li>

      <li class="rt-bc__sep" aria-hidden="true">/</li>

      {%- if bc_show_mid and bc_mid_label and bc_mid_url -%}
        <li class="rt-bc__item">
          <a class="rt-bc__link" href="{{ bc_mid_url }}">{{ bc_mid_label }}</a>
        </li>
        <li class="rt-bc__sep" aria-hidden="true">/</li>
      {%- endif -%}

      <li class="rt-bc__item">
        <span class="rt-bc__current" aria-current="page">{{ bc_label }}</span>
      </li>

    </ol>
  </nav>
</div>

<style>
  .rt-bc-outer{
    width: 100% !important;
    max-width: var(--page-width, 1200px);
    margin: 0 auto !important;

    background: #EDF0F2; /* ✅ updated */
    padding: 12px 12px 12px 16px !important;

    border-radius: 0 !important;

    text-align: left !important;
    justify-self: start !important;
    align-self: start !important;
    place-self: start !important;
  }

  .rt-bc{
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    text-align: left !important;
    font-family: inherit;
    font-size: 14px;
    font-weight: 500;
    line-height: 1.2;
    color: #003878;
  }

  .rt-bc__list{
    display: flex;
    justify-content: flex-start !important;
    align-items: center;
    gap: 8px;
    margin: 0 !important;
    padding: 0 !important;
    list-style: none !important;
    width: 100% !important;
    flex-wrap: wrap;
  }

  .rt-bc__link{
    color: #003878;
    text-decoration: none;
    transition: color .15s ease, text-decoration-color .15s ease;
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .rt-bc__link:hover{
    color: #FF7300;
    text-decoration: underline;
    text-decoration-color: #FF7300;
  }

  .rt-bc__home-ico{
    display: inline-flex;
    line-height: 0;
  }
  .rt-bc__home-ico svg{
    display: block;
    width: 16px;
    height: 16px;
    fill: currentColor;
  }

  .rt-bc__sep{ color: #003878; }

  .rt-bc__current{
    color: #003878;
    font-size: 14px;
    font-weight: 500;
  }

  @media (max-width: 749px){
    .rt-bc-outer{
      width: 100vw !important;
      max-width: none !important;
      margin-left: calc(50% - 50vw) !important;
      margin-right: calc(50% - 50vw) !important;
      padding: 12px 10px 12px 12px !important;
    }
  }
</style>

{% liquid
  assign raw_uid = block.id | default: section.id | default: 'diagonal-banner'
  assign uid = raw_uid | replace: ':', '-' | replace: '.', '-' | replace: '/', '-'

  assign banner_h = 380
  assign diag_top_x = 5
  assign diag_bottom_x = 250
  assign fold_w = 28
  assign band_w = 44
  assign band_top_y = 62

  assign delta = diag_bottom_x | minus: diag_top_x
  assign diag_at_band_y = delta | times: band_top_y | divided_by: banner_h | plus: diag_top_x

  assign img_url_700 = 'https://cdn.shopify.com/s/files/1/0670/4168/9713/files/Technisch_Maatwerk.webp?v=1772892582'
  assign img_url_mobile = 'https://cdn.shopify.com/s/files/1/0670/4168/9713/files/Technisch_Maatwerk.webp?v=1772892582'
  assign image_alt = 'Technisch Maatwerk'

  assign title = 'Maatwerk nodig?'
  assign subtitle = 'Rubber<span class="rt-xl">XL</span> denkt graag mee'
  assign description = 'Maatwerk en oplossingsgericht advies behoren tot onze sterkste punten. Kun je voor jouw toepassing niet het juiste product of een passende oplossing vinden? Neem dan gerust contact met ons op.'
  assign button_label = 'Contact opnemen'
  assign button_link = '/pages/maatwerk'
%}

<style>
 .rt-{{ uid }} {
  --rt-bg: #003878;
  --rt-btn-bg: #FF7300;
  --rt-btn-hover: #e66700;
  --rt-btn-text: #ffffff;
  --rt-text: #ffffff;
  --rt-radius: 8px;
  --rt-border: #A0B2C9;
}

.rt-{{ uid }}.rt-wrap {
  width: 100%;
  border-radius: var(--rt-radius);
  overflow: hidden;
  box-shadow: 0 20px 25px -5px rgba(0,0,0,.10), 0 10px 10px -5px rgba(0,0,0,.04);
  border: 1px solid var(--rt-border);
}

.rt-{{ uid }} .rt-banner {
  display: flex;
  min-height: {{ banner_h }}px;
  flex-direction: column;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-banner {
    flex-direction: row;
  }
}

.rt-{{ uid }} .rt-left {
  width: 100%;
  background: var(--rt-bg);
  color: var(--rt-text);
  padding: 24px;
  display: flex;
  align-items: center;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-left {
    width: 50%;
    padding: 48px;
  }
}

.rt-{{ uid }} .rt-content {
  width: 100%;
  max-width: 820px;
}

.rt-{{ uid }} .rt-head {
  font-size: 32px;
  margin: 0 0 24px;
  color: #fff;
}

.rt-{{ uid }} .rt-head-line {
  display: block;
}

.rt-{{ uid }} .rt-head-line + .rt-head-line {
  margin-top: 8px;
}

.rt-{{ uid }} .rt-desc {
  font-size: 16px;
  max-width: 600px;
  margin: 0 0 24px;
  color: #fff;
}

.rt-{{ uid }} .rt-btn {
  display: inline-block;
  padding: 16px 24px;
  background: var(--rt-btn-bg);
  color: var(--rt-btn-text);
  text-decoration: none;
  border-radius: 8px;
  font-weight: 700;
  transition: all .2s ease;
}

.rt-{{ uid }} .rt-btn:hover {
  background: var(--rt-btn-hover);
  transform: translateY(-2px);
  box-shadow: 0 10px 15px -3px rgba(0,0,0,.10);
}

.rt-{{ uid }} .rt-right {
  width: 100%;
  height: 220px;
  position: relative;
  background: var(--rt-bg);
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-right {
    width: 50%;
    height: auto;
  }
}

.rt-{{ uid }} .rt-right svg {
  display: none;
  width: 100%;
  height: 100%;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-right svg {
    display: block;
  }
}

.rt-{{ uid }} .rt-mobile-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-mobile-img {
    display: none;
  }
}
</style>

<div class="rt-wrap rt-{{ uid }}">
  <div class="rt-banner">
    <div class="rt-left">
      <div class="rt-content">
        <h2 class="rt-head">
          <span class="rt-head-line">{{ title }}</span>
          <span class="rt-head-line">{{ subtitle }}</span>
        </h2>

        <p class="rt-desc">{{ description }}</p>

        <a href="{{ button_link }}" class="rt-btn">{{ button_label }}</a>
      </div>
    </div>

    <div class="rt-right">
      <svg viewBox="0 0 700 {{ banner_h }}" preserveAspectRatio="xMinYMid slice" aria-hidden="true">
        <defs>
          <clipPath id="imgClip-{{ uid }}">
            <polygon points="{{ diag_top_x }},0 700,0 700,{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>
          <clipPath id="shadowOnPhotoSide-{{ uid }}">
            <polygon points="{{ diag_top_x }},0 700,0 700,{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>

          <filter id="sh_fold_soft-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="24" dy="1" stdDeviation="16" flood-color="#000" flood-opacity="0.14"/>
          </filter>

          <filter id="sh_band_only-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow in="SourceAlpha" dx="27" dy="17" stdDeviation="4.8" flood-color="#000" flood-opacity="0.22" result="ds1"/>
            <feDropShadow in="SourceAlpha" dx="52" dy="30" stdDeviation="26" flood-color="#000" flood-opacity="0.12" result="ds2"/>
            <feMerge>
              <feMergeNode in="ds1"/>
              <feMergeNode in="ds2"/>
            </feMerge>
          </filter>

          <linearGradient id="bandShine-{{ uid }}" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#ffffff" stop-opacity="0.00"/>
            <stop offset="25%" stop-color="#ffffff" stop-opacity="0.22"/>
            <stop offset="50%" stop-color="#ffffff" stop-opacity="0.06"/>
            <stop offset="75%" stop-color="#ffffff" stop-opacity="0.18"/>
            <stop offset="100%" stop-color="#ffffff" stop-opacity="0.00"/>
          </linearGradient>

          <clipPath id="bandClip-{{ uid }}">
            <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>
        </defs>

        {% if img_url_700 != blank %}
          <image
            href="{{ img_url_700 }}"
            x="0"
            y="0"
            width="700"
            height="{{ banner_h }}"
            clip-path="url(#imgClip-{{ uid }})"
            preserveAspectRatio="xMidYMid slice"
          />
        {% else %}
          <rect x="0" y="0" width="700" height="{{ banner_h }}" fill="#eee" clip-path="url(#imgClip-{{ uid }})" />
        {% endif %}

        <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#000" filter="url(#sh_band_only-{{ uid }})"/>
        <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#008CD2"/>

        <g clip-path="url(#bandClip-{{ uid }})" opacity="0.9">
          <rect x="0" y="0" width="700" height="{{ banner_h }}" fill="url(#bandShine-{{ uid }})"/>
        </g>

        <g clip-path="url(#shadowOnPhotoSide-{{ uid }})">
          <g filter="url(#sh_fold_soft-{{ uid }})">
            <polygon points="{{ diag_top_x | minus: fold_w }},0 {{ diag_top_x }},0 {{ diag_bottom_x }},{{ banner_h }} {{ diag_bottom_x | minus: fold_w }},{{ banner_h }}" fill="#003878"/>
          </g>
        </g>

        <polygon points="{{ diag_top_x | minus: fold_w }},0 {{ diag_top_x }},0 {{ diag_bottom_x }},{{ banner_h }} {{ diag_bottom_x | minus: fold_w }},{{ banner_h }}" fill="#003878"/>
        <polygon points="{{ diag_top_x }},0 {{ diag_top_x | plus: 2 }},0 {{ diag_bottom_x | plus: 2 }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#000" opacity="0.06"/>
      </svg>

      {% if img_url_mobile != blank %}
        <img
          src="{{ img_url_mobile }}"
          class="rt-mobile-img"
          alt="{{ image_alt | escape }}"
          loading="lazy"
          decoding="async"
          fetchpriority="low"
          width="800"
          height="380"
        >
      {% else %}
        <div class="rt-mobile-img" style="background:#eee;"></div>
      {% endif %}
    </div>
  </div>
</div>
